Verify And Decrypt Webhook Submission.code:
// Verify the X-FormSG-Signature header and decrypt the submission.
// Needs formSecretKey and webhookEndpoint in the credential.
// FormSG posts { data: { formId, submissionId, encryptedContent, ... } }.
processWebhook(
  // 1) The encrypted submission from the webhook body.
  $.data.data,
  // 2) The signature header sent by FormSG.
  $.request.headers['x-formsg-signature']
);

Decrypt Submission.code:
// Decrypt a submission (handy when testing with a saved payload).
// state.data becomes { responses: [{ question, answer, fieldType, ... }] }.
decryptSubmission($.data.data);

Decrypt Submission With Signature Check.code:
// Decrypt only if the signature matches the configured webhookEndpoint.
decryptSubmission($.data.data, {
  verifySignature: true,
  signatureHeader: $.request.headers['x-formsg-signature'],
});

Map Responses To Answers By Question.code:
// 1) Verify and decrypt the submission.
processWebhook($.data.data, $.request.headers['x-formsg-signature']);

// 2) Flatten responses into { 'Full name': 'Tan Mei Ling', ... }.
fn(state => {
  state.answers = state.data.responses.reduce((acc, r) => {
    // Checkbox and table fields use answerArray instead of answer.
    acc[r.question] = r.answer ?? r.answerArray;
    return acc;
  }, {});
  return state;
});
